1	package net.officefloor.hq.app.invoices;
2	
3	import java.math.BigDecimal;
4	import java.util.List;
5	import net.officefloor.hq.app.Audit;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.stereotype.Service;
8	import org.springframework.transaction.annotation.Transactional;
9	
10	/**
11	 * Business logic for invoices. Invoices are always viewed in the context of their project, so the
12	 * list is scoped by project id. The derived total the UI shows is computed by the front-end from the
13	 * returned rows; this service just surfaces the project's invoices in a stable order. Marking an
14	 * invoice paid flips its status and records an audit entry so the action can be checked later.
15	 */
16	@Service
17	public class InvoiceService {
18	
19	    private final InvoiceRepository repository;
20	    private final JdbcTemplate jdbc;
21	    private final Audit audit;
22	
23	    public InvoiceService(InvoiceRepository repository, JdbcTemplate jdbc, Audit audit) {
24	        this.repository = repository;
25	        this.jdbc = jdbc;
26	        this.audit = audit;
27	    }
28	
29	    @Transactional(readOnly = true)
30	    public List<InvoiceView> listForProject(Long projectId) {
31	        return jdbc.query(
32	                "SELECT id, project_id, amount, status FROM invoices WHERE project_id = ? ORDER BY id ASC",
33	                (rs, i) -> new InvoiceView(rs.getLong("id"), rs.getLong("project_id"),
34	                        rs.getBigDecimal("amount"), rs.getString("status")),
35	                projectId);
36	    }
37	
38	    @Transactional
39	    public InvoiceView create(Long projectId, BigDecimal amount) {
40	        if (projectId == null) {
41	            throw new IllegalArgumentException("An invoice requires a project");
42	        }
43	        if (amount == null) {
44	            throw new IllegalArgumentException("An invoice requires an amount");
45	        }
46	        if (amount.signum() <= 0) {
47	            throw new IllegalArgumentException("An invoice amount must be greater than zero");
48	        }
49	        Invoice invoice = new Invoice();
50	        invoice.setProjectId(projectId);
51	        invoice.setAmount(amount);
52	        Invoice saved = repository.save(invoice);
53	        return new InvoiceView(saved.getId(), saved.getProjectId(), saved.getAmount(),
54	                saved.getStatus());
55	    }
56	
57	    @Transactional
58	    public InvoiceView pay(Long invoiceId) {
59	        if (invoiceId == null) {
60	            throw new IllegalArgumentException("An invoice id is required");
61	        }
62	        jdbc.update("UPDATE invoices SET status = 'PAID' WHERE id = ?", invoiceId);
63	        InvoiceView invoice = jdbc.queryForObject(
64	                "SELECT id, project_id, amount, status FROM invoices WHERE id = ?",
65	                (rs, i) -> new InvoiceView(rs.getLong("id"), rs.getLong("project_id"),
66	                        rs.getBigDecimal("amount"), rs.getString("status")),
67	                invoiceId);
68	        audit.record("INVOICE_PAID id=" + invoice.getId() + " amount="
69	                + invoice.getAmount().setScale(2));
70	        return invoice;
71	    }
72	}
73

